\[ U_3= -B I_2 R_3=-\frac{R_1}{R_1+R_2}I_\mathrm{q} B R_3 = -6,2748\mathrm{V} \approx -6,27\mathrm{V}
\]
\[ U_4= \frac{R_4}{R_3+R_4}v U_2 = \frac{R_4}{R_3 + R_4}\cdot \frac{R_2}{R_1 + R_2}v U_\mathrm{q} = 4,6319\mathrm{V} \approx 4,63\mathrm{V}
\]
